// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PuttyV2, IERC1271, SignatureChecker} from "../src/PuttyV2.sol";

contract InvMutTest is Test, IERC1271 {
    PuttyV2 c;
    MockToken token;

    function setUp() public {
        c = new PuttyV2("", 0, address(this));
        token = new MockToken();
    }

    // maker is this contract; SignatureChecker falls back to ERC-1271 on it
    function isValidSignature(bytes32, bytes memory) external pure returns (bytes4) {
        return 0x1626ba7e;
    }

    function testFuzz_property(
        uint256 nowT,
        uint256 duration,
        uint256 expiration
    ) public {
        nowT = bound(nowT, 1, 1.7e9);
        duration = bound(duration, 0, 9_999 days);
        vm.assume(expiration > nowT);
        vm.warp(nowT);

        address[] memory whitelist = new address[](0);
        address[] memory floorTokens = new address[](0);
        PuttyV2.ERC20Asset[] memory erc20Assets = new PuttyV2.ERC20Asset[](0);
        PuttyV2.ERC721Asset[] memory erc721Assets = new PuttyV2.ERC721Asset[](0);

        PuttyV2.Order memory order = PuttyV2.Order({
            maker: address(this),
            isCall: false,
            isLong: true,
            baseAsset: address(token),
            strike: 0,
            premium: 0,
            duration: duration,
            expiration: expiration,
            nonce: 0,
            whitelist: whitelist,
            floorTokens: floorTokens,
            erc20Assets: erc20Assets,
            erc721Assets: erc721Assets
        });

        uint256[] memory floorAssetTokenIds = new uint256[](0);
        bytes memory sig = new bytes(65);

        c.fillOrder(order, sig, floorAssetTokenIds);

        // General rule: a long position's recorded expiration is exactly the
        // fill timestamp plus the order duration.
        assertTrue(
            c.positionExpirations(uint256(c.hashOrder(order))) == block.timestamp + duration,
            "position expiration must be fill time + duration"
        );
    }
}

contract MockToken {
    function transfer(address, uint256) external pure returns (bool) {
        return true;
    }

    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }

    function approve(address, uint256) external pure returns (bool) {
        return true;
    }
}
